SELECT 
FROM t_command_idempotency
WHERE caller_scope = #{callerScope}
  AND operation_type = #{operationType,javaType=com.paytech.risk.domain.enums.CommandOperationType}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.update:
UPDATE t_command_idempotency
SET response_ref = #{responseRef},
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE caller_scope = #{callerScope}
  AND operation_type = #{operationType,javaType=com.paytech.risk.domain.enums.CommandOperationType}
  AND idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = #{processingStatus,javaType=com.paytech.risk.domain.enums.CommandIdempotencyStatus}
  AND response_ref IS NULL

UPDATE t_command_idempotency
SET status = #{succeededStatus,javaType=com.paytech.risk.domain.enums.CommandIdempotencyStatus},
    response_ref = #{responseRef},
    update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler}
WHERE caller_scope = #{callerScope}
  AND operation_type = #{operationType,javaType=com.paytech.risk.domain.enums.CommandOperationType}
  AND idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = #{processingStatus,javaType=com.paytech.risk.domain.enums.CommandIdempotencyStatus}
  AND (response_ref IS NULL OR response_ref = #{responseRef})
